package com.oracle.banking.notification.service;
import com.oracle.banking.notification.dto.NotificationDtos.EmailRequest; import java.util.Map; import org.slf4j.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class NotificationKafkaListener { private static final Logger log=LoggerFactory.getLogger(NotificationKafkaListener.class); private final NotificationService service; public NotificationKafkaListener(NotificationService service){this.service=service;}
 @KafkaListener(topics={"registration-success","login-alert","transaction-created","bill-payment-created","card-blocked","card-unblocked","password-reset-request","security-alert"}) public void consume(Map<String,Object> event){String type=String.valueOf(event.getOrDefault("eventType","generic-notification")); Object recipient=event.get("recipient"); if(recipient==null){log.warn("Received {} event without recipient; notification was not sent",type);return;} @SuppressWarnings("unchecked") Map<String,String> variables=event.get("variables") instanceof Map<?,?> raw?(Map<String,String>)(Map<?,?>)raw:Map.of("message",String.valueOf(event.getOrDefault("message",type))); String template=String.valueOf(event.getOrDefault("templateName","GENERIC_NOTIFICATION")); service.send(new EmailRequest(String.valueOf(recipient),template,variables,type,String.valueOf(event.getOrDefault("referenceNumber","")))); log.info("Processed Kafka notification event {}",type);}}
